from thefuck.utils import replace_argument
from thefuck.specific.git import git_support


@git_support
def match(command):
    has_push = 'push' in command.script
    has_upstream = 'set-upstream' in command.stderr
    return has_push and has_upstream


@git_support
def get_new_command(command):
    # When --set-upstream or -u is supplied, drop it along with its value,
    # since git's own suggested command (which we build upon) already
    # contains --set-upstream plus its value
    idx = -1
    for opt in ('--set-upstream', '-u'):
        try:
            idx = command.script_parts.index(opt)
        except ValueError:
            continue

    if idx is not -1:
        command.script_parts.pop(idx)
        command.script_parts.pop(idx)

    suggestion = command.stderr.split('\n')[-3].strip().partition('git ')[2]
    base = " ".join(command.script_parts)
    return replace_argument(base, 'push', suggestion)
